import{_ as e,o as a,c as o,a2 as i}from"./chunks/framework.BGlkWkwp.js";const p=JSON.parse('{"title":"List","description":"","frontmatter":{},"headers":[],"relativePath":"components/list.md","filePath":"components/list.md"}'),d={name:"components/list.md"};function s(r,t,l,n,h,c){return a(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="list" tabindex="-1">List <a class="header-anchor" href="#list" aria-label="Permalink to &quot;List&quot;">​</a></h1><p>List is a column of <a href="./list-item">ListItems</a> and nothing else.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for items of one kind: documents, people, notifications. Put it where it reaches the edges of its container (a panel, a page), not in a container with padding. A switch, a checkbox or a radio is not a list item and goes in a <a href="./stack">Stack</a>; values in columns are a <a href="./table">Table</a>. When the items hold different things and must line up, <code>rows</code> raises their least height.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>label</code></td><td></td><td>The name of the list</td></tr><tr><td><code>role</code></td><td><code>list</code></td><td><code>group</code> for a list of choices (with <code>label</code>)</td></tr><tr><td><code>rows</code></td><td></td><td>The least item height: <code>mark</code>, <code>box</code>, <code>thumb</code> or <code>two</code></td></tr><tr><td><code>children</code></td><td>required</td><td>The ListItems</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The items touch: the list has no padding and no gap, and its outline runs from the top of the first item to the bottom of the last; the distance to its neighbours is the gap of the layout around it. <code>rows</code> makes every item at least as tall as one that holds a mark (<code>--kata-height-list-item-mark</code>), a small button (<code>--kata-height-list-item-lg</code>), a thumbnail (<code>--kata-height-thumbnail-row</code>) or two lines (<code>--kata-height-list-item-two</code>). With a <code>label</code> the list has its role and name.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/list/" title="List" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/list/" target="_blank" rel="noopener">List</a></figcaption></figure>',10)])])}const u=e(d,[["render",s]]);export{p as __pageData,u as default};
